#include <iostream>

template <typename T>
T clamp_value(T value, T low, T high) {
    if (value < low) {
        return low;
    }
    if (value > high) {
        return high;
    }
    return value;
}

int main() {
    std::cout << clamp_value(12, 0, 10) << "\n";
    std::cout << clamp_value(1.5, 0.0, 1.0) << "\n";
    return 0;
}
